assertion:
Check ($flow.Contains('if (agenda.Faction == null)') -and $flow.Contains('choice == 1 ? CourtAgendaState.Blocked')) 'Crown none closes ordinary business without a faction blocking charge.'
foreach ($name in @('Behaviors/CourtCouncilAgendas.cs', 'Behaviors/CourtExecutiveAgendas.cs')) {
    Check ((Read $name).Contains('agenda.PlayerSelectionConfirmed || agenda.IsFiled')) "Alternate nomination respects confirmed selection: $name"
}

foreach ($mutator in @('UpdatePlayerAgenda(old);', 'ideology.BeginCourtTerm(realm);', 'ElectiveSuccessionBehavior.Instance?.Maintain(realm, renewal: true);', 'OpenCrownTerm(realm, manager);')) {
    $pos = $open.IndexOf($mutator, [StringComparison]::Ordinal)
    Check ($pos -ge 0 -and $open.IndexOf('if (!CourtRulerUnchanged(realm, house, ruler)) return;', $pos, [StringComparison]::Ordinal) -gt $pos) "Term admission rechecked after $mutator"
}
